admin_router = APIRouter(
    prefix="/admin",
    dependencies=[Depends(require_org_admin)]
)

@admin_router.put("/organizations/{org_id}/sso-settings")
def update_org_sso(
    org_id: str,
    settings: SsoConfigSchema,
    admin: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    if admin.org_id != org_id and not admin.is_superuser:
        raise HTTPException(status_code=403, detail="Cannot alter SSO settings of another organization")

    org = db.query(Organization).filter(Organization.id == org_id).first()
    if not org:
        raise HTTPException(status_code=404, detail="Organization not found")

    org.idp_metadata_url = str(settings.idp_metadata_url)
    org.enforce_sso = settings.enforce_sso
    db.commit()
    return {"status": "sso_updated", "organization_id": org_id}
